package handler
import("encoding/json";"math";"net/http";"sort";"sync";"time")
type simulateRequest struct{PolicyID string `json:"policyId"`;ClientKey string `json:"clientKey"`;RequestCount int `json:"requestCount"`;Concurrency int `json:"concurrency"`;IntervalMs int `json:"intervalMs"`}
type TraceEntry struct{Sequence int `json:"sequence"`;StatusCode int `json:"statusCode"`;Outcome string `json:"outcome"`;RemainingTokens float64 `json:"remainingTokens"`;RetryAfterSec float64 `json:"retryAfterSec"`;LatencyUs float64 `json:"latencyUs"`;At string `json:"at"`}
func Handler(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json");w.Header().Set("Cache-Control","no-store");if r.Method!="POST"{w.Header().Set("Allow","POST");http.Error(w,`{"error":"method not allowed"}`,405);return};var q simulateRequest;if json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20)).Decode(&q)!=nil{http.Error(w,`{"error":"invalid JSON"}`,400);return};if q.ClientKey==""||len(q.ClientKey)>120||q.RequestCount<1||q.RequestCount>100||q.Concurrency<1||q.Concurrency>16||q.IntervalMs<0||q.IntervalMs>10000{http.Error(w,`{"error":"invalid simulation parameters"}`,400);return};appStore.mu.Lock();p,ok:=appStore.policies[q.PolicyID];appStore.mu.Unlock();if !ok{http.Error(w,`{"error":"unknown policy"}`,404);return}
trace:=make([]TraceEntry,q.RequestCount);jobs:=make(chan int);var wg sync.WaitGroup;workers:=q.Concurrency;if workers>q.RequestCount{workers=q.RequestCount};var scheduleMu sync.Mutex;next:=time.Now()
for n:=0;n<workers;n++{wg.Add(1);go func(){defer wg.Done();for i:=range jobs{if q.IntervalMs>0{scheduleMu.Lock();target:=next;now:=time.Now();if target.Before(now){target=now};next=target.Add(time.Duration(q.IntervalMs)*time.Millisecond);scheduleMu.Unlock();if d:=time.Until(target);d>0{time.Sleep(d)}};started:=time.Now();appStore.mu.Lock();cur:=appStore.policies[q.PolicyID];now:=time.Now();b:=appStore.bucketLocked(cur,q.ClientKey,now);refill(b,cur,now);e:=TraceEntry{Sequence:i+1,At:now.UTC().Format(time.RFC3339Nano)};if b.Tokens+1e-9>=cur.CostPerReq{b.Tokens-=cur.CostPerReq;e.StatusCode=200;e.Outcome="allowed"}else{e.StatusCode=429;e.Outcome="throttled";if cur.RefillPerSec>0{e.RetryAfterSec=math.Ceil((cur.CostPerReq-b.Tokens)/cur.RefillPerSec*1000)/1000}else{e.RetryAfterSec=-1}};e.RemainingTokens=math.Round(b.Tokens*100)/100;appStore.mu.Unlock();e.LatencyUs=float64(time.Since(started).Microseconds());trace[i]=e}}()}
for i:=0;i<q.RequestCount;i++{jobs<-i};close(jobs);wg.Wait();sort.Slice(trace,func(i,j int)bool{return trace[i].Sequence<trace[j].Sequence});allowed,throttled:=0,0;latency:=0.0;for _,e:=range trace{if e.StatusCode==200{allowed++}else{throttled++};latency+=e.LatencyUs};appStore.mu.Lock();cur:=appStore.policies[p.ID];b:=appStore.bucketLocked(cur,q.ClientKey,time.Now());refill(b,cur,time.Now());bucket:=BucketView{q.ClientKey,math.Round(b.Tokens*100)/100,cur.Capacity,math.Round(b.Tokens/cur.Capacity*1000)/10};appStore.mu.Unlock();json.NewEncoder(w).Encode(map[string]any{"policyId":q.PolicyID,"clientKey":q.ClientKey,"requestCount":q.RequestCount,"allowedCount":allowed,"throttledCount":throttled,"throttleRatePct":math.Round(float64(throttled)/float64(q.RequestCount)*1000)/10,"avgLatencyUs":math.Round(latency/float64(q.RequestCount)*10)/10,"trace":trace,"bucket":bucket,"completedAt":time.Now().UTC().Format(time.RFC3339)})}
